  "signalType": "gradient",
  "spec": "Extend smallsEstimate into a continuous contribution to computed.smallReadiness; surface the estimate and the breakdown threshold on the leaf.",
  "completionCriteria": [
    {
      "statement": "A higher complexity estimate measurably lowers the cached readiness gradient",
      "evaluator": "executable"
    }
  ]
}

uhCkkXCCwBWL8rgt6KAAnZGnzaqho4LMLdBXTLMs.description:
